#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE_D 4
#define BLOCK_SIZE_HW 64
#define KERNEL_SIZE 3

__global__ void conv_transpose3d_gather_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int stride, int padding, int groups,
    int C_in_per_group, int C_out_per_group,
    bool has_bias) {

    extern __shared__ float shared_weight[];

    int n = blockIdx.x / (C_out_per_group * groups);
    int temp = blockIdx.x % (C_out_per_group * groups);
    int group_id = temp / C_out_per_group;
    int c_out_local = temp % C_out_per_group;
    int c_out = group_id * C_out_per_group + c_out_local;

    if (n >= N) return;

    int weight_size = C_in_per_group * KERNEL_SIZE * KERNEL_SIZE * KERNEL_SIZE;

    for (int i = threadIdx.x; i < weight_size; i += blockDim.x) {
        int c_in_local = i / (KERNEL_SIZE * KERNEL_SIZE * KERNEL_SIZE);
        int spatial = i % (KERNEL_SIZE * KERNEL_SIZE * KERNEL_SIZE);
        int kd = spatial / (KERNEL_SIZE * KERNEL_SIZE);
        int kh = (spatial / KERNEL_SIZE) % KERNEL_SIZE;
        int kw = spatial % KERNEL_SIZE;

        int c_in = group_id * C_in_per_group + c_in_local;
        int weight_idx = ((c_in * C_out_per_group + c_out_local) * KERNEL_SIZE + kd) * KERNEL_SIZE * KERNEL_SIZE + kh * KERNEL_SIZE + kw;
        shared_weight[i] = __ldg(&weight[weight_idx]);
    }
    __syncthreads();

    int d_base = blockIdx.y * BLOCK_SIZE_D;
    int hw_base = blockIdx.z * BLOCK_SIZE_HW;

    for (int d_offset = 0; d_offset < BLOCK_SIZE_D; d_offset++) {
        int od = d_base + d_offset;
        if (od >= D_out) continue;

        for (int hw_offset = threadIdx.x; hw_offset < BLOCK_SIZE_HW; hw_offset += blockDim.x) {
            int hw_idx = hw_base + hw_offset;
            if (hw_idx >= H_out * W_out) continue;

            int oh = hw_idx / W_out;
            int ow = hw_idx % W_out;

            float sum = 0.0f;

            for (int kd = 0; kd < KERNEL_SIZE; kd++) {
                int id_temp = od + padding - kd;
                if (id_temp % stride != 0) continue;
                int id = id_temp / stride;
                if (id < 0 || id >= D_in) continue;

                for (int kh = 0; kh < KERNEL_SIZE; kh++) {
                    int ih_temp = oh + padding - kh;
                    if (ih_temp % stride != 0) continue;
                    int ih = ih_temp / stride;
                    if (ih < 0 || ih >= H_in) continue;

                    for (int kw = 0; kw < KERNEL_SIZE; kw++) {
                        int iw_temp = ow + padding - kw;
                        if (iw_temp % stride != 0) continue;
                        int iw = iw_temp / stride;
                        if (iw < 0 || iw >= W_in) continue;

                        for (int c_in_local = 0; c_in_local < C_in_per_group; c_in_local++) {
                            int c_in = group_id * C_in_per_group + c_in_local;
                            int input_idx = ((((n * C_in + c_in) * D_in + id) * H_in + ih) * W_in + iw);
                            int weight_offset = ((c_in_local * KERNEL_SIZE + kd) * KERNEL_SIZE + kh) * KERNEL_SIZE + kw;
                            sum += __ldg(&input[input_idx]) * shared_weight[weight_offset];
                        }
                    }
                }
            }

            if (has_bias) {
                sum += bias[c_out];
            }

            int output_idx = ((((n * C_out + c_out) * D_out + od) * H_out + oh) * W_out + ow);
            output[output_idx] = sum;
        }
    }
}

