    TORCH_CHECK(weight.is_contiguous(), "Weight must be contiguous");

    int N = x.size(0);
    int C_in = x.size(1);
    int D_in = x.size(2);
    int H_in = x.size(3);
    int W_in = x.size(4);

    int C_out = weight.size(0);
    int C_out_per_group = weight.size(1);

