#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define KERNEL_SIZE 3
#define KKK 27  // 3*3*3

// Specialized kernel for C_in_per_group == 8 (benchmark fast path)
// Each block handles one (n, c_out) output channel slice
// Grid: (N * C_out, ceil(D_out/BD), ceil(H_out*W_out/BHW))

#define BD 4
#define BHW 64

__global__ void conv_transpose3d_gather_k8(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int stride, int padding,
    int C_in_per_group, int C_out_per_group,
    bool has_bias) {

    // shared_weight layout: [C_in_per_group=8][KKK=27], total 216 floats = 864 bytes
    __shared__ float sw[8][KKK];

    int nc_out = blockIdx.x;
    int n       = nc_out / C_out;
    int c_out   = nc_out % C_out;
    int group_id     = c_out / C_out_per_group;
    int c_out_local  = c_out % C_out_per_group;

    if (n >= N) return;

    // Load weights for this output channel: weight[c_in, c_out_local, kd, kh, kw]
    // PyTorch ConvTranspose3d weight shape: [C_in, C_out/groups, kD, kH, kW]
    // group's c_in range: [group_id*C_in_per_group, (group_id+1)*C_in_per_group)
    // total taps to load = 8 * 27 = 216
    int total_w = C_in_per_group * KKK; // 8*27=216
    for (int i = threadIdx.x; i < total_w; i += blockDim.x) {
        int ci_local = i / KKK;
        int tap      = i % KKK;
        int kd = tap / 9;
        int kh = (tap / 3) % 3;
        int kw = tap % 3;
        int c_in_global = group_id * C_in_per_group + ci_local;
        // weight layout [C_in, C_out_per_group, kD, kH, kW]
        int widx = ((c_in_global * C_out_per_group + c_out_local) * KERNEL_SIZE + kd)
                   * KERNEL_SIZE * KERNEL_SIZE + kh * KERNEL_SIZE + kw;
        sw[ci_local][tap] = __ldg(&weight[widx]);
    }
    __syncthreads();

    int d_base  = blockIdx.y * BD;
    int hw_base = blockIdx.z * BHW;

    // Precompute base input pointer for this (n, group)
    int group_cin_base = group_id * C_in_per_group;
    long long input_n_base = (long long)n * C_in * D_in * H_in * W_in;
    long long input_ch_stride = (long long)D_in * H_in * W_in;

    for (int d_off = 0; d_off < BD; d_off++) {
        int od = d_base + d_off;
        if (od >= D_out) continue;

        // For stride=2, padding=1: only kd where (od+1-kd) even and id in [0,D_in)
        // kd_start = (od + padding) % stride = (od+1) & 1
        int kd_start = (od + padding) & 1; // stride==2

        for (int hw_off = threadIdx.x; hw_off < BHW; hw_off += blockDim.x) {
            int hw_idx = hw_base + hw_off;
            if (hw_idx >= H_out * W_out) continue;

            int oh = hw_idx / W_out;
            int ow = hw_idx % W_out;

            int kh_start = (oh + padding) & 1;
            int kw_start = (ow + padding) & 1;

            float sum = 0.0f;

            for (int kd = kd_start; kd < KERNEL_SIZE; kd += stride) {
                int id = (od + padding - kd) / stride;
                if ((unsigned)id >= (unsigned)D_in) continue;

                for (int kh = kh_start; kh < KERNEL_SIZE; kh += stride) {
                    int ih = (oh + padding - kh) / stride;
                    if ((unsigned)ih >= (unsigned)H_in) continue;

                    for (int kw = kw_start; kw < KERNEL_SIZE; kw += stride) {
                        int iw = (ow + padding - kw) / stride;
                        if ((unsigned)iw >= (unsigned)W_in) continue;

                        int tap = kd * 9 + kh * 3 + kw;

                        // Hoisted input pointer to (n, group_cin_base, id, ih, iw)
