                        long long spatial_off = (long long)id * H_in * W_in + ih * W_in + iw;
                        long long in_base = input_n_base + (long long)group_cin_base * input_ch_stride + spatial_off;

                        // Unrolled 8-channel accumulation
                        sum += __ldg(&input[in_base + 0 * input_ch_stride]) * sw[0][tap];
                        sum += __ldg(&input[in_base + 1 * input_ch_stride]) * sw[1][tap];
                        sum += __ldg(&input[in_base + 2 * input_ch_stride]) * sw[2][tap];
                        sum += __ldg(&input[in_base + 3 * input_ch_stride]) * sw[3][tap];
                        sum += __ldg(&input[in_base + 4 * input_ch_stride]) * sw[4][tap];
                        sum += __ldg(&input[in_base + 5 * input_ch_stride]) * sw[5][tap];
                        sum += __ldg(&input[in_base + 6 * input_ch_stride]) * sw[6][tap];
