            if (hw_idx >= H_out * W_out) continue;
            int oh = hw_idx / W_out;
            int ow = hw_idx % W_out;
            float sum = 0.0f;
            for (int kd = 0; kd < KERNEL_SIZE; kd++) {
                int id_t = od + padding - kd;
                if (id_t % stride != 0) continue;
                int id = id_t / stride;
                if ((unsigned)id >= (unsigned)D_in) continue;
                for (int kh = 0; kh < KERNEL_SIZE; kh++) {
